import{_ as s,p as a,q as n,Y as e}from"./framework-e1bed10d.js";const l="/my-blog/assets/copy-2a9fa2a8.png",i="/my-blog/assets/server-f6153727.png",t={},r=e('<h1 id="_17主从复制" tabindex="-1"><a class="header-anchor" href="#_17主从复制" aria-hidden="true">#</a> 17主从复制</h1><h2 id="定义" tabindex="-1"><a class="header-anchor" href="#定义" aria-hidden="true">#</a> 定义</h2><p>主从复制是指将主数据库的 DDL 和 DML 操作通过二进制日志传到从库服务器中，然后在从库上对这些日志重新执行（也叫重做），从而使得从库和主库的数据保持同步</p><h2 id="应用场景" tabindex="-1"><a class="header-anchor" href="#应用场景" aria-hidden="true">#</a> 应用场景</h2><ul><li>主库出现问题，可以快速切换到从库提供服务</li><li>实现读写分离，降低主库的访问压力</li><li>可以在从库中执行备份，以避免备份期间影响主库服务</li></ul><h2 id="原理" tabindex="-1"><a class="header-anchor" href="#原理" aria-hidden="true">#</a> 原理</h2><p>MySQL主从复制的核心就是 二进制日志，具体的过程如下</p><p><img src="'+l+'" alt="原理"></p><p>从上图来看，复制分成三步：</p><ol><li>Master 主库在事务提交时，会把数据变更记录在二进制日志文件Binlog中</li><li>从库读取主库的二进制日志文件Binlog ，写入到从库的中继日志Relay Log</li><li>slave重做中继日志中的事件，将改变反映它自己的数据</li></ol><h2 id="搭建" tabindex="-1"><a class="header-anchor" href="#搭建" aria-hidden="true">#</a> 搭建</h2><h3 id="服务器准备" tabindex="-1"><a class="header-anchor" href="#服务器准备" aria-hidden="true">#</a> 服务器准备</h3><p>准备好两台服务器之后，在上述的两台服务器中分别安装好MySQL，并完成基础的初始化准备(安装、密码配置等操作)工作</p><p><img src="'+i+`" alt="server"></p><h3 id="主库配置" tabindex="-1"><a class="header-anchor" href="#主库配置" aria-hidden="true">#</a> 主库配置</h3><ol><li>修改配置文件 /etc/my.cnf</li></ol><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># mysql 服务ID，保证整个集群环境中唯一，取值范围：1 – 232-1，默认为1</span>
server-id<span class="token operator">=</span><span class="token number">1</span>
<span class="token comment"># 是否只读,1 代表只读, 0 代表读写</span>
read-only<span class="token operator">=</span><span class="token number">0</span>
<span class="token comment"># 忽略的数据, 指不需要同步的数据库</span>
<span class="token comment"># binlog-ignore-db=mysql</span>
<span class="token comment"># 指定同步的数据库</span>
<span class="token comment"># binlog-do-db=db01</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ol start="2"><li>重启MySQL服务器</li></ol><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>systemctl restart mysqld
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><ol start="3"><li>登录mysql，创建远程连接的账号，并授予主从复制权限</li></ol><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 创建itcast用户，并设置密码，该用户可在任意主机连接该MySQL服务</span>
CREATE <span class="token environment constant">USER</span> <span class="token string">&#39;itcast&#39;</span>@<span class="token string">&#39;%&#39;</span> IDENTIFIED WITH mysql_native_password BY <span class="token string">&#39;Root@123456&#39;</span><span class="token punctuation">;</span>
<span class="token comment"># 为 &#39;itcast&#39;@&#39;%&#39; 用户分配主从复制权限</span>
GRANT REPLICATION SLAVE ON *.* TO <span class="token string">&#39;itcast&#39;</span>@<span class="token string">&#39;%&#39;</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ol start="4"><li>通过指令，查看二进制日志坐标</li></ol><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>show master status <span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><ul><li>file : 从哪个日志文件开始推送日志文件</li><li>position ： 从哪个位置开始推送日志</li><li>binlog_ignore_db : 指定不需要同步的数据库</li></ul><h3 id="从库配置" tabindex="-1"><a class="header-anchor" href="#从库配置" aria-hidden="true">#</a> 从库配置</h3><ol><li>修改配置文件 /etc/my.cnf</li></ol><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># mysql 服务ID，保证整个集群环境中唯一，取值范围：1 – 2^32-1，和主库不一样即可</span>
server-id<span class="token operator">=</span><span class="token number">2</span>
<span class="token comment"># 是否只读,1 代表只读, 0 代表读写</span>
read-only<span class="token operator">=</span><span class="token number">1</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ol start="2"><li>重新启动MySQL服务</li></ol><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>systemctl restart mysqld
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><ol start="3"><li>登录mysql，设置主库配置</li></ol><p>8.0.23及以后</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>CHANGE REPLICATION SOURCE TO <span class="token assign-left variable">SOURCE_HOST</span><span class="token operator">=</span><span class="token string">&#39;192.168.200.200&#39;</span>, <span class="token assign-left variable">SOURCE_USER</span><span class="token operator">=</span><span class="token string">&#39;itcast&#39;</span>,
<span class="token assign-left variable">SOURCE_PASSWORD</span><span class="token operator">=</span><span class="token string">&#39;Root@123456&#39;</span>, <span class="token assign-left variable">SOURCE_LOG_FILE</span><span class="token operator">=</span><span class="token string">&#39;binlog.000004&#39;</span>,
<span class="token assign-left variable">SOURCE_LOG_POS</span><span class="token operator">=</span><span class="token number">663</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>8.0.23 之前</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>CHANGE MASTER TO <span class="token assign-left variable">MASTER_HOST</span><span class="token operator">=</span><span class="token string">&#39;192.168.200.200&#39;</span>, <span class="token assign-left variable">MASTER_USER</span><span class="token operator">=</span><span class="token string">&#39;itcast&#39;</span>,
<span class="token assign-left variable">MASTER_PASSWORD</span><span class="token operator">=</span><span class="token string">&#39;Root@123456&#39;</span>, <span class="token assign-left variable">MASTER_LOG_FILE</span><span class="token operator">=</span><span class="token string">&#39;binlog.000004&#39;</span>,
<span class="token assign-left variable">MASTER_LOG_POS</span><span class="token operator">=</span><span class="token number">663</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ol start="4"><li>开启同步操作</li></ol><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>start replica <span class="token punctuation">;</span> <span class="token comment"># 8.0.22之后</span>
start slave <span class="token punctuation">;</span> <span class="token comment"># 8.0.22之前</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><ol start="5"><li>查看主从同步状态</li></ol><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>show replica status <span class="token punctuation">;</span> <span class="token comment"># 8.0.22之后</span>
show slave status <span class="token punctuation">;</span> <span class="token comment"># 8.0.22之前</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div>`,38),o=[r];function c(d,p){return a(),n("div",null,o)}const v=s(t,[["render",c],["__file","17slave.html.vue"]]);export{v as default};
